      lvSel.innerHTML = `<option value="1">${T('Ușor (dreptunghiuri)', 'Easy (rectangles)')}</option><option value="2">${T('Mediu', 'Medium')}</option><option value="3">${T('Greu', 'Hard')}</option>`; lvSel.value = cl;
