    const P = (x, y) => ({ x, y });
    const rotp = (p, c, th) => { const dx = p.x - c.x, dy = p.y - c.y, co = Math.cos(th), si = Math.sin(th); return { x: c.x + dx * co - dy * si, y: c.y + dx * si + dy * co }; };
