    const arcPts = (c, r, a0, a1, n) => { const o = []; n = n || 24; for (let i = 0; i <= n; i++) { const a = a0 + (a1 - a0) * i / n; o.push(P(c.x + r * Math.cos(a), c.y + r * Math.sin(a))); } return o; };
    const sector = (c, r, a0, a1, n) => [c, ...arcPts(c, r, a0, a1, n)];
