        line(a, b, col, w, dash) { el('line', { x1: X(a.x), y1: Y(a.y), x2: X(b.x), y2: Y(b.y), stroke: col || '#ccc', 'stroke-width': w || 2, 'stroke-dasharray': dash || '', 'stroke-linecap': 'round' }); },
