        const fA = ang(A, B), wA = nrm(ang(A, C) - ang(A, B)), fB = ang(B, C), wB = nrm(ang(B, A) - ang(B, C)), fC = ang(C, A), wC = nrm(ang(C, B) - ang(C, A));
