        const dim = (pts, c, o) => g.poly(pts, c, { o, stroke: '#fff', w: 1.2 });
        const sA = sector(A, r, fA, fA + wA, 18), sB = sector(B, r, fB, fB + wB, 18), sC = sector(C, r, fC, fC + wC, 18);
