        g.text(P(-4 + ma + .2, -1.6), 'MA = (a+b)/2 = ' + f(ma), 15, '#fff', 'start'); g.text(P(-4 + mg + .2, -2.15), 'MG = √(a·b) = ' + f(mg), 15, COL.r, 'start');
