function openInfoModal(title, bodyHtml) {
  const backdrop = document.getElementById('info-modal-backdrop');
  const titleEl = document.getElementById('info-modal-title');
  const bodyEl = document.getElementById('info-modal-body');
  if (!backdrop || !titleEl || !bodyEl) return;
  titleEl.textContent = title;
  bodyEl.innerHTML = bodyHtml;
  backdrop.classList.add('show');
  const toolbarPosTop = document.getElementById('toolbar-pos-top');
  const toolbarPosBottom = document.getElementById('toolbar-pos-bottom');
  if (toolbarPosTop && toolbarPosBottom) {
    const current = getToolbarPosition();
    (current === 'top' ? toolbarPosTop : toolbarPosBottom).checked = true;
    toolbarPosTop.addEventListener('change', () => { if (toolbarPosTop.checked) setToolbarPosition('top'); });
    toolbarPosBottom.addEventListener('change', () => { if (toolbarPosBottom.checked) setToolbarPosition('bottom'); });
  }
  const themeDark = document.getElementById('theme-dark');
  const themeLight = document.getElementById('theme-light');
  if (themeDark && themeLight) {
    const currentTheme = getTheme();
    (currentTheme === 'light' ? themeLight : themeDark).checked = true;
    themeDark.addEventListener('change', () => { if (themeDark.checked) setTheme('dark'); });
    themeLight.addEventListener('change', () => { if (themeLight.checked) setTheme('light'); });
  }
  const hiddenLinesToggle = document.getElementById('toggle-hidden-lines');
  if (hiddenLinesToggle) {
    // Bifat = "arată toate muchiile continue" → SOLID_SHOW_HIDDEN_LINES = false.
    // Nebifat (implicit) = muchiile din spate întrerupte → SOLID_SHOW_HIDDEN_LINES = true.
    hiddenLinesToggle.checked = !SOLID_SHOW_HIDDEN_LINES;
    hiddenLinesToggle.addEventListener('change', () => {
      SOLID_SHOW_HIDDEN_LINES = !hiddenLinesToggle.checked;
      rebuildAllSolid3DStrokes();
      redrawStrokes();
      drawSelectionHighlights();
    });
  }
}
function closeInfoModal() {
  const backdrop = document.getElementById('info-modal-backdrop');
  if (backdrop) backdrop.classList.remove('show');
}

// Reconstruiește (la aceeași rotație) toate corpurile 3D deja desenate, pe toate paginile —
// folosit când se schimbă comutatorul de linii ascunse, ca schimbarea să se vadă imediat și
// pe formele plasate deja, nu doar pe cele noi.
function rebuildAllSolid3DStrokes() {
  pages.forEach(page => {
    (page.strokes || []).forEach(stroke => {
      if (stroke.type === 'solid3d' && SOLID_SHAPES[stroke.shape]) {
        rotateSolid3D(stroke, stroke.rotationY || 0);
      }
    });
  });
}

const btnHelp = document.getElementById('btn-help');
if (btnHelp) btnHelp.addEventListener('click', () => openInfoModal(LANG === 'en' ? 'Help' : 'Ajutor', LANG === 'en' ? HELP_CONTENT_HTML_EN : HELP_CONTENT_HTML));
const btnLicense = document.getElementById('btn-license');
if (btnLicense) btnLicense.addEventListener('click', () => openInfoModal(LANG === 'en' ? 'License' : 'Licență', LANG === 'en' ? LICENSE_CONTENT_HTML_EN : LICENSE_CONTENT_HTML));
const infoModalClose = document.getElementById('info-modal-close');
if (infoModalClose) infoModalClose.addEventListener('click', closeInfoModal);
const infoModalBackdrop = document.getElementById('info-modal-backdrop');
if (infoModalBackdrop) {
  infoModalBackdrop.addEventListener('click', (e) => {
    if (e.target === infoModalBackdrop) closeInfoModal();
  });
}

// ================================================================
// INITIALIZARE
// ================================================================

document.getElementById('btn-pen').classList.add('active');
tool = 'pen';

updateGeoToolContrast();
// Apel de siguranță, ca tabla să fie corect dimensionată de la început —
// dar initCanvas() dimensionează canvas-urile TABLEI, deci trebuie să ruleze
// doar cât timp tabla e suprafața activă (altfel ar corupe dimensiunile
// ferestrei PDF, dacă aceasta a devenit între timp suprafața activă).
setTimeout(() => {
  const wasActive = activeSurface;
  if (wasActive !== 'board') activatePane('board');
  initCanvas();
  if (wasActive !== 'board') activatePane(wasActive);
}, 100);

const langSelectEl = document.getElementById('lang-select');
if (langSelectEl) langSelectEl.addEventListener('change', (e) => setLanguage(e.target.value));
setLanguage(LANG);
applyToolbarPosition(getToolbarPosition());
applyTheme(getTheme());

setTimeout(checkAutosaveOnStartup, 600);

// Înregistrează Service Worker-ul pentru suport offline (funcționează doar
// pe http(s), nu și dacă fișierul e deschis direct de pe disc cu file://).
if ('serviceWorker' in navigator && location.protocol.startsWith('http')) {
  window.addEventListener('load', () => {
    navigator.serviceWorker.register('sw.js').catch((e) => {
      console.warn('Service worker nu a putut fi înregistrat:', e);
    });
  });
}


// ================================================================
// CULEGERE DE MATEMATICĂ — generator de fișe, încorporat în tablă
// ================================================================
// Butonul „Culegere” deschide modulul (culegere.html) într-un strat pe tot
// ecranul, peste tablă. Când în modul se apasă „Trimite pe tablă”, paginile
// din previzualizare ajung aici ca imagini (fără PDF) — câte o pagină de
// tablă pentru fiecare pagină a fișei — sau, la „Trimite ca PDF”, ca fișă PDF.
// Același protocol de mesaje (tabla-ping / tabla-ready / culegere-pdf /
// tabla-ok) funcționează și cu versiunea online a culegerii, deschisă separat.
(function initCulegere() {
  const btn = document.getElementById('btn-culegere');
  const overlay = document.getElementById('culegere-overlay');
  const frame = document.getElementById('culegere-frame');
  if (!btn || !overlay || !frame) return;
  const CULEGERE_URL = 'culegere.html?embed=1&v=v401';  // v=… ocolește memoria cache a browserului la fiecare versiune nouă

  function openCulegere() {
    if (!frame.getAttribute('src')) frame.setAttribute('src', CULEGERE_URL); // încărcat la cerere
    overlay.style.display = 'block';
    document.documentElement.classList.add('culegere-open');
    try { frame.contentWindow.focus(); } catch (e) {}
  }
  function closeCulegere() {
    overlay.style.display = 'none';
    document.documentElement.classList.remove('culegere-open');
    try { window.focus(); } catch (e) {}
  }
  btn.addEventListener('click', openCulegere);
  window.openCulegere = openCulegere;
  window.closeCulegere = closeCulegere;

  function loadSheetImage(src) {
    return new Promise((resolve) => {
      const im = new Image();
      im.onload = () => resolve(im);
      im.onerror = () => resolve(null);
      im.src = src;
    });
  }

  // Așază paginile fișei pe tablă: prima pe pagina curentă (dacă e goală),
  // restul pe pagini noi; fiecare imagine încape întreagă în ecran și e blocată
  // (ca să scrii pe ea fără să o muți din greșeală — se poate debloca oricând).
  async function placeSheetPages(dataUrls, marks) {
    const byPage = groupSolMarks(marks) || {};
    if (typeof pdfModeActive !== 'undefined' && pdfModeActive) setBoardMode(false);
    activatePane('board');
    let placed = 0, firstIdx = -1;
    for (let i = 0; i < dataUrls.length; i++) {
      const img = await loadSheetImage(dataUrls[i]);
      if (!img) continue;
      let page = getCurrentPage();
      if (placed > 0 || page.strokes.length > 0 || page.images.length > 0) {
        addPage();
        page = getCurrentPage();
      }
      if (firstIdx < 0) firstIdx = currentPageIdx;
      const vw = wrap.clientWidth, vh = wrap.clientHeight;
      const scale = boardZoom || 1;
      const ratio = (img.naturalWidth || img.width) / (img.naturalHeight || img.height);
      // imaginea ocupă toată lățimea tablei (orizontal); înălțimea urmează proporțiile paginii
      const sw = vw, sh = sw / ratio;
      const x = (0 - boardPanX) / scale;
      const y = sh <= vh ? ((vh - sh) / 2 - boardPanY) / scale : (0 - boardPanY) / scale;
      addImageToPage(page, img, x, y, sw / scale, sh / scale);
      const imgData = page.images[page.images.length - 1];
      imgData.locked = true;
      if (byPage[i + 1]) imgData.solMarks = byPage[i + 1];
      undoStack.push({ type: 'imageAdd', page, img: imgData });
      placed++;
    }
    redoStack = [];
    if (firstIdx >= 0 && firstIdx !== currentPageIdx) {
      currentPageIdx = firstIdx;
      drawBg(); redrawStrokes();
    }
    renderImages();
    updateStatus();
    // fișa are fundal alb: dacă creionul e alb (sau foarte deschis), trecem automat pe roșu
    if (placed > 0 && /^#?(f{3}|f{6})$/i.test(String(color || '').replace('#', ''))) {
      try { setColorFromButton('#ff0000', 'qa-color-red'); } catch (er) {}
    }
    return placed;
  }

  function paneHasAnnotations() {
    if (!pdfDoc) return false;
    const pd = (pdfPanes.top && pdfPanes.top.pagesData) || {};
    return Object.keys(pd).some(k => pd[k] && ((pd[k].strokes && pd[k].strokes.length) || (pd[k].images && pd[k].images.length)));
  }
  // Construiește local (instant, fără rețea) o fișă PDF A4 din paginile randate și o încarcă în
  // modulul PDF al tablei, unde se afișează pe toată lățimea ferestrei.
  async function openSheetInPdfPane(dataUrls, marks) {
    if (!window.jspdf || !window.jspdf.jsPDF) {
      showToast(trMsg('⚠ Biblioteca PDF nu e disponibilă')); return false;
    }
    const { jsPDF } = window.jspdf;
    const doc = new jsPDF({ unit: 'mm', format: 'a4', compress: true });
    for (let i = 0; i < dataUrls.length; i++) {
      if (i) doc.addPage();
      doc.addImage(dataUrls[i], 'JPEG', 0, 0, 210, 297, undefined, 'FAST');
    }
    const buf = doc.output('arraybuffer');
    loadPdfFromArrayBuffer(buf, marks);
    return true;
  }

  function reply(src, msg) { try { src.postMessage(msg, '*'); } catch (e) {} }

  window.addEventListener('message', async (e) => {
    const d = e.data;
    if (!d || typeof d !== 'object' || !e.source) return;
    const fromFrame = e.source === frame.contentWindow;
    const fromOpener = !!window.opener && e.source === window.opener;
    if (d.type === 'tabla-ping') { if (fromFrame || fromOpener) reply(e.source, { type: 'tabla-ready' }); return; }
    if (!fromFrame && !fromOpener) return; // acceptăm doar mesaje de la culegere
    if (d.type === 'culegere-close') { if (fromFrame) closeCulegere(); return; }
    if (d.type === 'culegere-pages' && Array.isArray(d.pages)) {
      const imgs = d.pages.filter(p => typeof p === 'string' && p.startsWith('data:image/'));
      if (!imgs.length) { showToast(trMsg('⚠ Nu s-a putut încărca fișa trimisă')); return; }
      if (paneHasAnnotations() && !confirm(LANG === 'en'
        ? 'The PDF sheet currently open has your annotations; they will be lost if it is replaced. Continue?'
        : 'Fișa PDF deschisă acum are adnotări de-ale tale; se vor pierde dacă o înlocuiești. Continui?')) {
        reply(e.source, { type: 'tabla-cancel' }); return;
      }
      if (await openSheetInPdfPane(imgs, d.marks)) {
        reply(e.source, { type: 'tabla-ok' });
        if (fromFrame) closeCulegere(); else { try { window.focus(); } catch (er) {} }
      }
      return;
    }
    if (d.type === 'culegere-board-pages' && Array.isArray(d.pages)) {
      const okPages = d.pages.map((p, ix) => ({ p, ix })).filter(o => typeof o.p === 'string' && o.p.startsWith('data:image/'));
      const n = await placeSheetPages(okPages.map(o => o.p), (Array.isArray(d.marks) ? d.marks : []).map(m => { const k = okPages.findIndex(o => o.ix === m.page); return k < 0 ? null : { ...m, page: k }; }).filter(Boolean));
      if (n > 0) {
        showToast(trMsg(`✓ Fișă trimisă pe tablă (${n} ${n === 1 ? 'pagină' : 'pagini'})`));
        reply(e.source, { type: 'tabla-ok' });
        if (fromFrame) closeCulegere(); else { try { window.focus(); } catch (er) {} }
      } else {
        showToast(trMsg('⚠ Nu s-a putut încărca fișa trimisă'));
      }
      return;
    }
    if (d.type === 'culegere-pdf' && d.buffer) {
      loadPdfFromArrayBuffer(d.buffer, d.marks);
      reply(e.source, { type: 'tabla-ok' });
      if (fromFrame) closeCulegere(); else { try { window.focus(); } catch (er) {} }
    }
  });

  // deschisă din versiunea online a culegerii (fereastră separată, #culegere): anunțăm că tabla e gata
  if (location.hash === '#culegere' && window.opener) reply(window.opener, { type: 'tabla-ready' });
})();
